  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Olsalazine has a systemic availability of only 2.3% after a 1 g oral dose in healthy volunteers, providing direct human evidence that an oral drug can have F far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Vismodegib, a lipophilic and poorly soluble drug, has an absolute oral bioavailability of 31.8% in healthy subjects, showing that lipophilicity and poor solubility do not by themselves force F below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C40"],
      "claim": "Tolcapone, which contains nitro and phenolic groups, has an absolute oral bioavailability of about 60% in healthy volunteers, indicating that such functionalities are compatible with high F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low oral bioavailability because the query is niclosamide, a salicylanilide anthelmintic known to be poorly absorbed; the retrieved evidence is weakly transferable, with only olsalazine providing direct low-F support and several distant high-F drugs providing contradictory context.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule was retrieved; all analogues have low Morgan similarity (<0.28).",
    "The only low-F analogue (olsalazine) is structurally distant and its poor absorption mechanism differs from the query's lipophilic salicylanilide core.",
    "High-F analogues are also distant and do not share the salicylanilide core, limiting their transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

